  1→package auth
  2→
  3→import (
  4→	"bytes"
  5→	"context"
  6→	"encoding/json"
  7→	"fmt"
  8→	"io"
  9→	"net/http"
 10→	"net/url"
 11→	"strings"
 12→
 13→	apiurl "github.com/entireio/cli/cmd/entire/cli/api"
 14→)
 15→
 16→const (
 17→	maxResponseBytes = 1 << 20
 18→	clientID         = "entire-cli"
 19→)
 20→
 21→type Client struct {
 22→	httpClient *http.Client
 23→	baseURL    string
 24→}
 25→
 26→type DeviceAuthStart struct {
 27→	DeviceCode              string `json:"device_code"`
 28→	UserCode                string `json:"user_code"`
 29→	VerificationURI         string `json:"verification_uri"`
 30→	VerificationURIComplete string `json:"verification_uri_complete"`
 31→	ExpiresIn               int    `json:"expires_in"`
 32→	Interval                int    `json:"interval"`
 33→}
 34→
 35→type DeviceAuthPoll struct {
 36→	AccessToken string `json:"access_token,omitempty"`
 37→	TokenType   string `json:"token_type,omitempty"`
 38→	ExpiresIn   int    `json:"expires_in,omitempty"`
 39→	Scope       string `json:"scope,omitempty"`
 40→	Error       string `json:"error,omitempty"`
 41→}
 42→
 43→type errorResponse struct {
 44→	Error string `json:"error"`
 45→}
 46→
 47→func NewClient(httpClient *http.Client) *Client {
 48→	if httpClient == nil {
 49→		httpClient = &http.Client{}
 50→	}
 51→
 52→	return &Client{
 53→		httpClient: httpClient,
 54→		baseURL:    apiurl.BaseURL(),
 55→	}
 56→}
 57→
 58→func (c *Client) BaseURL() string {
 59→	return c.baseURL
 60→}
 61→
 62→func (c *Client) StartDeviceAuth(ctx context.Context) (*DeviceAuthStart, error) {
 63→	body := url.Values{}
 64→	body.Set("client_id", clientID)
 65→	body.Set("scope", "cli")
 66→
 67→	resp, err := c.postForm(ctx, "/oauth/device/code", body)
 68→	if err != nil {
 69→		return nil, fmt.Errorf("start device auth: %w", err)
 70→	}
 71→	defer resp.Body.Close()
 72→
 73→	if resp.StatusCode != http.StatusOK {
 74→		return nil, readAPIError(resp, "start device auth")
 75→	}
 76→
 77→	var result DeviceAuthStart
 78→	if err := decodeJSONStrict(resp.Body, &result); err != nil {
 79→		return nil, fmt.Errorf("decode device auth start response: %w", err)
 80→	}
 81→
 82→	return &result, nil
 83→}
 84→
 85→func (c *Client) PollDeviceAuth(ctx context.Context, deviceCode string) (*DeviceAuthPoll, error) {
 86→	body := url.Values{}
 87→	body.Set("grant_type", "urn:ietf:params:oauth:grant-type:device_code")
 88→	body.Set("client_id", clientID)
 89→	body.Set("device_code", deviceCode)
 90→
 91→	resp, err := c.postForm(ctx, "/oauth/token", body)
 92→	if err != nil {
 93→		return nil, fmt.Errorf("poll device auth: %w", err)
 94→	}
 95→	defer resp.Body.Close()
 96→
 97→	if resp.StatusCode != http.StatusOK {
 98→		apiErr, err := readAPIErrorResponse(resp)
 99→		if err != nil {
100→			return nil, fmt.Errorf("poll device auth: %w", err)
101→		}
102→		return &DeviceAuthPoll{Error: apiErr.Error}, nil
103→	}
104→
105→	var result DeviceAuthPoll
106→	if err := decodeJSON(resp.Body, &result); err != nil {
107→		return nil, fmt.Errorf("decode device auth poll response: %w", err)
108→	}
109→
110→	return &result, nil
111→}
112→
113→// postForm sends a POST request with form-encoded body to an API-relative path.
114→func (c *Client) postForm(ctx context.Context, path string, body url.Values) (*http.Response, error) {
115→	endpoint, err := apiurl.ResolveURLFromBase(c.baseURL, path)
116→	if err != nil {
117→		return nil, fmt.Errorf("resolve URL %s: %w", path, err)
118→	}
119→
120→	req, err := http.NewRequestWithContext(ctx, http.MethodPost, endpoint, strings.NewReader(body.Encode()))
121→	if err != nil {
122→		return nil, fmt.Errorf("create request: %w", err)
123→	}
124→
125→	req.Header.Set("Accept", "application/json")
126→	req.Header.Set("Content-Type", "application/x-www-form-urlencoded")
127→	req.Header.Set("User-Agent", clientID)
128→
129→	resp, err := c.httpClient.Do(req)
130→	if err != nil {
131→		return nil, fmt.Errorf("request %s: %w", path, err)
132→	}
133→
134→	return resp, nil
135→}
136→
137→func readAPIErrorResponse(resp *http.Response) (*errorResponse, error) {
138→	body, err := io.ReadAll(io.LimitReader(resp.Body, maxResponseBytes))
139→	if err != nil {
140→		return nil, fmt.Errorf("status %d", resp.StatusCode)
141→	}
142→
143→	var apiErr errorResponse
144→	if err := json.Unmarshal(body, &apiErr); err == nil && strings.TrimSpace(apiErr.Error) != "" {
145→		return &apiErr, nil
146→	}
147→
148→	text := strings.TrimSpace(string(body))
149→	if text != "" {
150→		return nil, fmt.Errorf("status %d: %s", resp.StatusCode, text)
151→	}
152→
153→	return nil, fmt.Errorf("status %d", resp.StatusCode)
154→}
155→
156→func readAPIError(resp *http.Response, action string) error {
157→	apiErr, err := readAPIErrorResponse(resp)
158→	if err == nil {
159→		return fmt.Errorf("%s: %s", action, apiErr.Error)
160→	}
161→	return fmt.Errorf("%s: %w", action, err)
162→}
163→
164→func decodeJSON(r io.Reader, dest any) error {
165→	return decodeJSONWithOptions(r, dest, false)
166→}
167→
168→func decodeJSONStrict(r io.Reader, dest any) error {
169→	return decodeJSONWithOptions(r, dest, true)
170→}
171→
172→func decodeJSONWithOptions(r io.Reader, dest any, strict bool) error {
173→	body, err := io.ReadAll(io.LimitReader(r, maxResponseBytes))
174→	if err != nil {
175→		return fmt.Errorf("read JSON response: %w", err)
176→	}
177→
178→	dec := json.NewDecoder(bytes.NewReader(body))
179→	if strict {
180→		dec.DisallowUnknownFields()
181→	}
182→	if err := dec.Decode(dest); err != nil {
183→		return fmt.Errorf("decode JSON response: %w", err)
184→	}
185→
186→	return nil
187→}
