  1→package trail
  2→
  3→import (
  4→	"encoding/json"
  5→	"errors"
  6→	"fmt"
  7→	"strings"
  8→	"time"
  9→
 10→	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
 11→	"github.com/entireio/cli/cmd/entire/cli/paths"
 12→
 13→	"github.com/go-git/go-git/v6"
 14→	"github.com/go-git/go-git/v6/plumbing"
 15→	"github.com/go-git/go-git/v6/plumbing/filemode"
 16→	"github.com/go-git/go-git/v6/plumbing/object"
 17→)
 18→
 19→const (
 20→	metadataFile    = "metadata.json"
 21→	discussionFile  = "discussion.json"
 22→	checkpointsFile = "checkpoints.json"
 23→)
 24→
 25→// ErrTrailNotFound is returned when a trail cannot be found.
 26→var ErrTrailNotFound = errors.New("trail not found")
 27→
 28→// Store provides CRUD operations for trail metadata on the entire/trails/v1 branch.
 29→type Store struct {
 30→	repo *git.Repository
 31→}
 32→
 33→// NewStore creates a new trail store backed by the given git repository.
 34→func NewStore(repo *git.Repository) *Store {
 35→	return &Store{repo: repo}
 36→}
 37→
 38→// EnsureBranch creates the entire/trails/v1 orphan branch if it doesn't exist.
 39→func (s *Store) EnsureBranch() error {
 40→	refName := plumbing.NewBranchReferenceName(paths.TrailsBranchName)
 41→	_, err := s.repo.Reference(refName, true)
 42→	if err == nil {
 43→		return nil // Branch already exists
 44→	}
 45→
 46→	// Create orphan branch with empty tree
 47→	emptyTreeHash, err := checkpoint.BuildTreeFromEntries(s.repo, make(map[string]object.TreeEntry))
 48→	if err != nil {
 49→		return fmt.Errorf("failed to build empty tree: %w", err)
 50→	}
 51→
 52→	authorName, authorEmail := checkpoint.GetGitAuthorFromRepo(s.repo)
 53→	commitHash, err := checkpoint.CreateCommit(s.repo, emptyTreeHash, plumbing.ZeroHash, "Initialize trails branch", authorName, authorEmail)
 54→	if err != nil {
 55→		return fmt.Errorf("failed to create initial commit: %w", err)
 56→	}
 57→
 58→	newRef := plumbing.NewHashReference(refName, commitHash)
 59→	if err := s.repo.Storer.SetReference(newRef); err != nil {
 60→		return fmt.Errorf("failed to set branch reference: %w", err)
 61→	}
 62→	return nil
 63→}
 64→
 65→// Write writes trail metadata, discussion, and checkpoints to the entire/trails/v1 branch.
 66→// If checkpoints is nil, an empty checkpoints list is written.
 67→func (s *Store) Write(metadata *Metadata, discussion *Discussion, checkpoints *Checkpoints) error {
 68→	if metadata.TrailID.IsEmpty() {
 69→		return errors.New("trail ID is required")
 70→	}
 71→
 72→	if err := s.EnsureBranch(); err != nil {
 73→		return fmt.Errorf("failed to ensure trails branch: %w", err)
 74→	}
 75→
 76→	commitHash, rootTreeHash, err := s.getBranchRef()
 77→	if err != nil {
 78→		return fmt.Errorf("failed to get branch ref: %w", err)
 79→	}
 80→
 81→	// Build blob entries for the trail's 3 files
 82→	trailEntries, err := s.buildTrailEntries(metadata, discussion, checkpoints)
 83→	if err != nil {
 84→		return err
 85→	}
 86→
 87→	// Splice into tree at [shard, suffix] — preserves sibling trails automatically
 88→	shard, suffix := metadata.TrailID.ShardParts()
 89→	newTreeHash, err := checkpoint.UpdateSubtree(
 90→		s.repo, rootTreeHash,
 91→		[]string{shard, suffix},
 92→		trailEntries,
 93→		checkpoint.UpdateSubtreeOptions{MergeMode: checkpoint.ReplaceAll},
 94→	)
 95→	if err != nil {
 96→		return fmt.Errorf("failed to update subtree: %w", err)
 97→	}
 98→
 99→	commitMsg := fmt.Sprintf("Trail: %s (%s)", metadata.Title, metadata.TrailID)
100→	return s.commitAndUpdateRef(newTreeHash, commitHash, commitMsg)
101→}
102→
103→// buildTrailEntries creates blob objects for a trail's 3 files and returns them as tree entries.
104→func (s *Store) buildTrailEntries(metadata *Metadata, discussion *Discussion, checkpoints *Checkpoints) ([]object.TreeEntry, error) {
105→	if discussion == nil {
106→		discussion = &Discussion{Comments: []Comment{}}
107→	}
108→	if checkpoints == nil {
109→		checkpoints = &Checkpoints{Checkpoints: []CheckpointRef{}}
110→	}
111→
112→	type fileSpec struct {
113→		name string
114→		data any
115→	}
116→	files := []fileSpec{
117→		{metadataFile, metadata},
118→		{discussionFile, discussion},
119→		{checkpointsFile, checkpoints},
120→	}
121→
122→	entries := make([]object.TreeEntry, 0, len(files))
123→	for _, f := range files {
124→		jsonBytes, err := json.MarshalIndent(f.data, "", "  ")
125→		if err != nil {
126→			return nil, fmt.Errorf("failed to marshal %s: %w", f.name, err)
127→		}
128→		blobHash, err := checkpoint.CreateBlobFromContent(s.repo, jsonBytes)
129→		if err != nil {
130→			return nil, fmt.Errorf("failed to create %s blob: %w", f.name, err)
131→		}
132→		entries = append(entries, object.TreeEntry{
133→			Name: f.name,
134→			Mode: filemode.Regular,
135→			Hash: blobHash,
136→		})
137→	}
138→
139→	return entries, nil
140→}
141→
142→// Read reads a trail by its ID from the entire/trails/v1 branch.
143→func (s *Store) Read(trailID ID) (*Metadata, *Discussion, *Checkpoints, error) {
144→	if err := ValidateID(string(trailID)); err != nil {
145→		return nil, nil, nil, err
146→	}
147→
148→	tree, err := s.getBranchTree()
149→	if err != nil {
150→		return nil, nil, nil, err
151→	}
152→
153→	basePath := trailID.Path() + "/"
154→
155→	// Read metadata
156→	metadataEntry, err := tree.FindEntry(basePath + metadataFile)
157→	if err != nil {
158→		return nil, nil, nil, fmt.Errorf("trail %s not found: %w", trailID, err)
159→	}
160→	metadataBlob, err := s.repo.BlobObject(metadataEntry.Hash)
161→	if err != nil {
162→		return nil, nil, nil, fmt.Errorf("failed to read metadata blob: %w", err)
163→	}
164→	metadataReader, err := metadataBlob.Reader()
165→	if err != nil {
166→		return nil, nil, nil, fmt.Errorf("failed to open metadata reader: %w", err)
167→	}
168→	defer metadataReader.Close()
169→
170→	var metadata Metadata
171→	if err := json.NewDecoder(metadataReader).Decode(&metadata); err != nil {
172→		return nil, nil, nil, fmt.Errorf("failed to decode metadata: %w", err)
173→	}
174→
175→	// Read discussion (optional, may not exist yet)
176→	var discussion Discussion
177→	discussionEntry, err := tree.FindEntry(basePath + discussionFile)
178→	if err == nil {
179→		discussionBlob, blobErr := s.repo.BlobObject(discussionEntry.Hash)
180→		if blobErr == nil {
181→			discussionReader, readerErr := discussionBlob.Reader()
182→			if readerErr == nil {
183→				//nolint:errcheck,gosec // best-effort decode of optional discussion
184→				json.NewDecoder(discussionReader).Decode(&discussion)
185→				_ = discussionReader.Close()
186→			}
187→		}
188→	}
189→
190→	// Read checkpoints (optional, may not exist yet)
191→	var checkpoints Checkpoints
192→	checkpointsEntry, err := tree.FindEntry(basePath + checkpointsFile)
193→	if err == nil {
194→		checkpointsBlob, blobErr := s.repo.BlobObject(checkpointsEntry.Hash)
195→		if blobErr == nil {
196→			checkpointsReader, readerErr := checkpointsBlob.Reader()
197→			if readerErr == nil {
198→				//nolint:errcheck,gosec // best-effort decode of optional checkpoints
199→				json.NewDecoder(checkpointsReader).Decode(&checkpoints)
200→				_ = checkpointsReader.Close()
201→			}
202→		}
203→	}
204→
205→	return &metadata, &discussion, &checkpoints, nil
206→}
207→
208→// FindByBranch finds a trail for the given branch name.
209→// Returns (nil, nil) if no trail exists for the branch.
210→func (s *Store) FindByBranch(branchName string) (*Metadata, error) {
211→	trails, err := s.List()
212→	if err != nil {
213→		return nil, err
214→	}
215→
216→	for _, t := range trails {
217→		if t.Branch == branchName {
218→			return t, nil
219→		}
220→	}
221→	return nil, nil //nolint:nilnil // nil, nil means "not found" — callers check both
222→}
223→
224→// List returns all trail metadata from the entire/trails/v1 branch.
225→func (s *Store) List() ([]*Metadata, error) {
226→	tree, err := s.getBranchTree()
227→	if err != nil {
228→		// Branch doesn't exist yet — no trails
229→		return nil, nil //nolint:nilerr // Expected when no trails exist yet
230→	}
231→
232→	var trails []*Metadata
233→	entries := make(map[string]object.TreeEntry)
234→	if err := checkpoint.FlattenTree(s.repo, tree, "", entries); err != nil {
235→		return nil, fmt.Errorf("failed to flatten tree: %w", err)
236→	}
237→
238→	// Find all metadata.json files
239→	for path, entry := range entries {
240→		if !strings.HasSuffix(path, "/"+metadataFile) {
241→			continue
242→		}
243→
244→		blob, err := s.repo.BlobObject(entry.Hash)
245→		if err != nil {
246→			continue
247→		}
248→		reader, err := blob.Reader()
249→		if err != nil {
250→			continue
251→		}
252→
253→		var metadata Metadata
254→		decodeErr := json.NewDecoder(reader).Decode(&metadata)
255→		_ = reader.Close()
256→		if decodeErr != nil {
257→			continue
258→		}
259→
260→		trails = append(trails, &metadata)
261→	}
262→
263→	return trails, nil
264→}
265→
266→// Update updates an existing trail's metadata. It reads the current metadata,
267→// applies the provided update function, and writes it back.
268→func (s *Store) Update(trailID ID, updateFn func(*Metadata)) error {
269→	// ValidateID is called by Read, no need to duplicate here
270→	metadata, discussion, checkpoints, err := s.Read(trailID)
271→	if err != nil {
272→		return fmt.Errorf("failed to read trail for update: %w", err)
273→	}
274→
275→	updateFn(metadata)
276→	metadata.UpdatedAt = time.Now()
277→
278→	return s.Write(metadata, discussion, checkpoints)
279→}
280→
281→// AddCheckpoint prepends a checkpoint reference to a trail's checkpoints list (newest first).
282→// Only reads and writes the checkpoints.json file — metadata and discussion are untouched.
283→func (s *Store) AddCheckpoint(trailID ID, ref CheckpointRef) error {
284→	if err := ValidateID(string(trailID)); err != nil {
285→		return err
286→	}
287→
288→	if err := s.EnsureBranch(); err != nil {
289→		return fmt.Errorf("failed to ensure trails branch: %w", err)
290→	}
291→
292→	commitHash, rootTreeHash, err := s.getBranchRef()
293→	if err != nil {
294→		return fmt.Errorf("failed to get branch ref: %w", err)
295→	}
296→
297→	// Navigate to the trail's subtree and read only checkpoints.json
298→	shard, suffix := trailID.ShardParts()
299→	trailTree, err := s.navigateToTrailTree(rootTreeHash, shard, suffix)
300→	if err != nil {
301→		return fmt.Errorf("failed to read checkpoints for trail %s: %w", trailID, err)
302→	}
303→
304→	checkpoints, err := s.readCheckpointsFromTrailTree(trailTree)
305→	if err != nil {
306→		return fmt.Errorf("failed to read checkpoints for trail %s: %w", trailID, err)
307→	}
308→
309→	// Prepend new ref (newest first)
310→	checkpoints.Checkpoints = append(checkpoints.Checkpoints, CheckpointRef{})
311→	copy(checkpoints.Checkpoints[1:], checkpoints.Checkpoints[:len(checkpoints.Checkpoints)-1])
312→	checkpoints.Checkpoints[0] = ref
313→
314→	// Create new blob and splice back — MergeKeepExisting preserves metadata.json and discussion.json
315→	checkpointsJSON, err := json.MarshalIndent(checkpoints, "", "  ")
316→	if err != nil {
317→		return fmt.Errorf("failed to marshal checkpoints: %w", err)
318→	}
319→	blobHash, err := checkpoint.CreateBlobFromContent(s.repo, checkpointsJSON)
320→	if err != nil {
321→		return fmt.Errorf("failed to create checkpoints blob: %w", err)
322→	}
323→
324→	newTreeHash, err := checkpoint.UpdateSubtree(
325→		s.repo, rootTreeHash,
326→		[]string{shard, suffix},
327→		[]object.TreeEntry{{Name: checkpointsFile, Mode: filemode.Regular, Hash: blobHash}},
328→		checkpoint.UpdateSubtreeOptions{MergeMode: checkpoint.MergeKeepExisting},
329→	)
330→	if err != nil {
331→		return fmt.Errorf("failed to update subtree: %w", err)
332→	}
333→
334→	commitMsg := fmt.Sprintf("Add checkpoint to trail: %s", trailID)
335→	return s.commitAndUpdateRef(newTreeHash, commitHash, commitMsg)
336→}
337→
338→// Delete removes a trail from the entire/trails/v1 branch.
339→func (s *Store) Delete(trailID ID) error {
340→	if err := ValidateID(string(trailID)); err != nil {
341→		return err
342→	}
343→
344→	if err := s.EnsureBranch(); err != nil {
345→		return fmt.Errorf("failed to ensure trails branch: %w", err)
346→	}
347→
348→	commitHash, rootTreeHash, err := s.getBranchRef()
349→	if err != nil {
350→		return fmt.Errorf("failed to get branch ref: %w", err)
351→	}
352→
353→	// Verify the trail exists by navigating the tree at O(depth)
354→	shard, suffix := trailID.ShardParts()
355→	if _, err := s.navigateToTrailTree(rootTreeHash, shard, suffix); err != nil {
356→		return err
357→	}
358→
359→	// Delete the trail's subtree by removing it from the shard directory
360→	newTreeHash, err := checkpoint.UpdateSubtree(
361→		s.repo, rootTreeHash,
362→		[]string{shard},
363→		nil,
364→		checkpoint.UpdateSubtreeOptions{
365→			MergeMode:   checkpoint.MergeKeepExisting,
366→			DeleteNames: []string{suffix},
367→		},
368→	)
369→	if err != nil {
370→		return fmt.Errorf("failed to update subtree: %w", err)
371→	}
372→
373→	commitMsg := fmt.Sprintf("Delete trail: %s", trailID)
374→	return s.commitAndUpdateRef(newTreeHash, commitHash, commitMsg)
375→}
376→
377→// navigateToTrailTree walks rootTree → shard → suffix and returns the trail's subtree.
378→func (s *Store) navigateToTrailTree(rootTreeHash plumbing.Hash, shard, suffix string) (*object.Tree, error) {
379→	rootTree, err := s.repo.TreeObject(rootTreeHash)
