143→		}
144→		trails = filtered
145→	} else if !showAll {
146→		// By default, hide merged and closed trails
147→		var filtered []*trail.Metadata
148→		for _, t := range trails {
149→			if t.Status != trail.StatusMerged && t.Status != trail.StatusClosed {
150→				filtered = append(filtered, t)
151→			}
152→		}
153→		trails = filtered
154→	}
155→
156→	// Sort by updated_at descending
157→	sort.Slice(trails, func(i, j int) bool {
158→		return trails[i].UpdatedAt.After(trails[j].UpdatedAt)
159→	})
160→
161→	if jsonOutput {
162→		enc := json.NewEncoder(w)
163→		enc.SetIndent("", "  ")
164→		if err := enc.Encode(trails); err != nil {
165→			return fmt.Errorf("failed to encode JSON: %w", err)
166→		}
167→		return nil
168→	}
169→
170→	if len(trails) == 0 {
171→		hiddenCount := totalCount - len(trails)
172→		if hiddenCount > 0 {
173→			fmt.Fprintf(w, "No active trails found. %d merged/closed trail(s) hidden — use --all to show.\n", hiddenCount)
174→		} else {
175→			fmt.Fprintln(w, "No trails found.")
176→			fmt.Fprintln(w)
177→			fmt.Fprintln(w, "Commands:")
178→			fmt.Fprintln(w, "  entire trail create   Create a trail for the current branch")
179→			fmt.Fprintln(w, "  entire trail list     List all trails")
180→			fmt.Fprintln(w, "  entire trail update   Update trail metadata")
181→		}
182→		return nil
183→	}
184→
185→	// Table output
186→	fmt.Fprintf(w, "%-30s %-40s %-13s %-15s %s\n", "BRANCH", "TITLE", "STATUS", "AUTHOR", "UPDATED")
187→	for _, t := range trails {
188→		branch := stringutil.TruncateRunes(t.Branch, 30, "...")
189→		title := stringutil.TruncateRunes(t.Title, 40, "...")
190→		fmt.Fprintf(w, "%-30s %-40s %-13s %-15s %s\n",
191→			branch, title, t.Status, stringutil.TruncateRunes(t.Author, 15, "..."), timeAgo(t.UpdatedAt))
192→	}
193→
194→	return nil
195→}
