383→func runTrailUpdate(w, errW io.Writer, statusStr, title, body, branch string, labelAdd, labelRemove []string) error {
384→	repo, err := strategy.OpenRepository(context.Background())
385→	if err != nil {
386→		return fmt.Errorf("failed to open repository: %w", err)
387→	}
388→
389→	// Determine branch
390→	if branch == "" {
391→		branch, err = GetCurrentBranch(context.Background())
392→		if err != nil {
393→			return fmt.Errorf("failed to determine current branch: %w", err)
394→		}
395→	}
396→
397→	store := trail.NewStore(repo)
398→	metadata, err := store.FindByBranch(branch)
399→	if err != nil {
400→		return fmt.Errorf("failed to find trail: %w", err)
401→	}
402→	if metadata == nil {
403→		return fmt.Errorf("no trail found for branch %q", branch)
404→	}
405→
406→	// Interactive mode when no flags are provided
407→	noFlags := statusStr == "" && title == "" && body == "" && labelAdd == nil && labelRemove == nil
408→	if noFlags {
409→		// Build status options with current value as default.
410→		// Exclude "merged" and "closed" unless the trail is already in that status
411→		// (otherwise the select would silently reset to the first option).
412→		var statusOptions []huh.Option[string]
413→		for _, s := range trail.ValidStatuses() {
414→			if (s == trail.StatusMerged || s == trail.StatusClosed) && s != metadata.Status {
415→				continue
416→			}
417→			label := string(s)
418→			if s == metadata.Status {
419→				label += " (current)"
420→			}
421→			statusOptions = append(statusOptions, huh.NewOption(label, string(s)))
422→		}
423→		statusStr = string(metadata.Status)
424→		title = metadata.Title
425→		body = metadata.Body
426→
427→		form := NewAccessibleForm(
428→			huh.NewGroup(
429→				huh.NewSelect[string]().
430→					Title("Status").
431→					Options(statusOptions...).
432→					Value(&statusStr),
433→				huh.NewInput().
434→					Title("Title").
435→					Value(&title),
436→				huh.NewText().
437→					Title("Body").
438→					Value(&body),
439→			),
440→		)
441→		if formErr := form.Run(); formErr != nil {
442→			return fmt.Errorf("form cancelled: %w", formErr)
443→		}
444→	}
445→
446→	// Validate status if provided
447→	if statusStr != "" {
448→		status := trail.Status(statusStr)
449→		if !status.IsValid() {
450→			return fmt.Errorf("invalid status %q: valid values are %s", statusStr, formatValidStatuses())
451→		}
452→	}
453→
454→	err = store.Update(metadata.TrailID, func(m *trail.Metadata) {
455→		if statusStr != "" {
456→			m.Status = trail.Status(statusStr)
457→		}
458→		if title != "" {
459→			m.Title = title
460→		}
461→		if body != "" {
462→			m.Body = body
463→		}
464→		for _, l := range labelAdd {
465→			if !slices.Contains(m.Labels, l) {
466→				m.Labels = append(m.Labels, l)
467→			}
468→		}
469→		for _, l := range labelRemove {
470→			m.Labels = slices.DeleteFunc(m.Labels, func(v string) bool { return v == l })
471→		}
472→	})
473→	if err != nil {
474→		return fmt.Errorf("failed to update trail: %w", err)
475→	}
476→
477→	fmt.Fprintf(w, "Updated trail for branch %s\n", branch)
478→
479→	if err := strategy.PushTrailsBranch(context.Background(), "origin"); err != nil {
480→		fmt.Fprintf(errW, "Warning: failed to push trail data: %v\n", err)
481→	}
482→
483→	return nil
484→}
