559→// fetchTrailsBranch fetches the remote trails branch so we see trails from collaborators.
560→// Best-effort: silently ignores errors (e.g., no remote, no network).
561→func fetchTrailsBranch() {
562→	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
563→	defer cancel()
564→	branchName := paths.TrailsBranchName
565→	refSpec := fmt.Sprintf("+refs/heads/%s:refs/remotes/origin/%s", branchName, branchName)
566→
567→	cmd := exec.CommandContext(ctx, "git", "fetch", "origin", refSpec)
568→	// Ensure non-interactive fetch in hook/agent contexts
569→	cmd.Stdin = nil
570→	cmd.Env = append(os.Environ(), "GIT_TERMINAL_PROMPT=0")
571→	_ = cmd.Run() //nolint:errcheck // best-effort fetch
