574→// getTrailAuthor returns the GitHub username for the trail author.
575→// Falls back to git user.name if gh CLI is unavailable or not authenticated.
576→func getTrailAuthor(repo *git.Repository) string {
577→	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
578→	defer cancel()
579→	cmd := exec.CommandContext(ctx, "gh", "api", "user", "-q", ".login")
580→	if output, err := cmd.Output(); err == nil {
581→		if login := strings.TrimSpace(string(output)); login != "" {
582→			return login
583→		}
584→	}
585→	name, _ := strategy.GetGitAuthorFromRepo(repo)
586→	return name
