589→// slugifyTitle converts a title string into a branch-friendly slug.
590→// Example: "Add user authentication" -> "add-user-authentication"
591→func slugifyTitle(title string) string {
592→	s := strings.ToLower(strings.TrimSpace(title))
593→	// Replace spaces and underscores with hyphens
594→	s = strings.NewReplacer(" ", "-", "_", "-").Replace(s)
595→	// Remove anything that's not alphanumeric, hyphen, or slash
596→	var b strings.Builder
597→	prevHyphen := false
598→	for _, r := range s {
599→		if (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') || r == '/' {
600→			b.WriteRune(r)
601→			prevHyphen = false
602→		} else if r == '-' && !prevHyphen {
603→			b.WriteRune('-')
604→			prevHyphen = true
605→		}
606→	}
607→	return strings.Trim(b.String(), "-")
608→}
